import React, { useEffect, useState } from "react";
import axios from "axios";
import AlertBox from "./AlertBox";

function AssignmentsTeacher() {
  const teacherId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [assignments, setAssignments] = useState([]);
  const [submissions, setSubmissions] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState("");
  const [selectedAssignmentId, setSelectedAssignmentId] = useState("");
  const [alert, setAlert] = useState(null);

  const [formData, setFormData] = useState({
    course_id: "",
    title: "",
    description: "",
    due_date: ""
  });

  useEffect(() => {
    fetchTeacherCourses();
  }, []);

  const fetchTeacherCourses = async () => {
    try {
      const res = await axios.get("http://127.0.0.1:8000/courses");
      const allCourses = res.data.courses || [];

      const myCourses = allCourses.filter(
        (course) => String(course.teacher_id) === String(teacherId)
      );

      setCourses(myCourses);
    } catch (err) {
      console.error("Error fetching teacher courses:", err);
    }
  };

  const loadAssignments = async (courseId) => {
    try {
      const res = await axios.get(`http://127.0.0.1:8000/assignments/${courseId}`);
      setAssignments(res.data.assignments || []);
      setSubmissions([]);
      setSelectedAssignmentId("");
    } catch (err) {
      console.error("Error loading assignments:", err);
    }
  };

  const loadSubmissions = async (assignmentId) => {
    try {
      const res = await axios.get(
        `http://127.0.0.1:8000/assignment-submissions/${assignmentId}`
      );
      setSubmissions(res.data.submissions || []);
    } catch (err) {
      console.error("Error loading submissions:", err);
      setSubmissions([]);
    }
  };

  const handleCourseChange = (e) => {
    const value = e.target.value;
    setSelectedCourse(value);

    setFormData({
      ...formData,
      course_id: value
    });

    if (value) {
      loadAssignments(value);
    } else {
      setAssignments([]);
      setSubmissions([]);
      setSelectedAssignmentId("");
    }
  };

  const handleAssignmentSelect = (e) => {
    const value = e.target.value;
    setSelectedAssignmentId(value);

    if (value) {
      loadSubmissions(value);
    } else {
      setSubmissions([]);
    }
  };

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.course_id) {
      setAlert({
        message: "Please select a course first",
        type: "error"
      });
      return;
    }

    try {
      const payload = {
        course_id: parseInt(formData.course_id),
        teacher_id: parseInt(teacherId),
        title: formData.title,
        description: formData.description,
        due_date: formData.due_date
      };

      const res = await axios.post(
        "http://127.0.0.1:8000/create-assignment",
        payload
      );

      setAlert({
        message: res.data.message,
        type: "success"
      });

      setFormData({
        course_id: selectedCourse || "",
        title: "",
        description: "",
        due_date: ""
      });

      if (selectedCourse) {
        loadAssignments(selectedCourse);
      }
    } catch (err) {
      console.error("Assignment creation error:", err);
      setAlert({
        message: "Assignment creation failed",
        type: "error"
      });
    }
  };

  return (
    <div>
      {alert && (
        <AlertBox
          message={alert.message}
          type={alert.type}
          onClose={() => setAlert(null)}
        />
      )}

      <h2 style={{ color: "#6a1b9a", marginBottom: "20px" }}>
        Teacher Assignments
      </h2>

      <div
        style={{
          display: "grid",
          gridTemplateColumns: "1fr 1fr",
          gap: "25px",
          marginBottom: "25px"
        }}
      >
        {/* Create Assignment */}
        <div style={panel}>
          <h3 style={heading}>Create Assignment</h3>

          <form onSubmit={handleSubmit} style={formStyle}>
            <select
              name="course_id"
              value={formData.course_id}
              onChange={handleCourseChange}
              style={inputStyle}
            >
              <option value="">Select Course</option>
              {courses.map((course) => (
                <option key={course.id} value={course.id}>
                  {course.title} {course.subject_code ? `(${course.subject_code})` : ""}
                </option>
              ))}
            </select>

            <input
              type="text"
              name="title"
              placeholder="Assignment Title"
              value={formData.title}
              onChange={handleChange}
              style={inputStyle}
            />

            <textarea
              name="description"
              placeholder="Assignment Question / Description"
              value={formData.description}
              onChange={handleChange}
              rows="4"
              style={inputStyle}
            />

            <input
              type="date"
              name="due_date"
              value={formData.due_date}
              onChange={handleChange}
              style={inputStyle}
            />

            <button type="submit" style={primaryBtn}>
              Create Assignment
            </button>
          </form>
        </div>

        {/* Assignment List */}
        <div style={panel}>
          <h3 style={heading}>Assignments in Selected Course</h3>

          {!selectedCourse ? (
            <p>Select a course to view assignments.</p>
          ) : assignments.length === 0 ? (
            <p>No assignments created yet.</p>
          ) : (
            <>
              <select
                value={selectedAssignmentId}
                onChange={handleAssignmentSelect}
                style={inputStyle}
              >
                <option value="">Select Assignment</option>
                {assignments.map((a) => (
                  <option key={a.id} value={a.id}>
                    {a.title}
                  </option>
                ))}
              </select>

              {assignments.map((a) => (
                <div key={a.id} style={card}>
                  <h4 style={{ marginBottom: "6px" }}>{a.title}</h4>
                  <p style={{ marginBottom: "6px", color: "#555" }}>
                    {a.description}
                  </p>
                  <p style={{ margin: 0 }}>
                    <strong>Due Date:</strong> {a.due_date}
                  </p>
                </div>
              ))}
            </>
          )}
        </div>
      </div>

      {/* Student Submissions */}
      <div style={panel}>
        <h3 style={heading}>Student Submissions</h3>

        {!selectedAssignmentId ? (
          <p>Select an assignment to view submissions.</p>
        ) : submissions.length === 0 ? (
          <p>No submissions found yet.</p>
        ) : (
          submissions.map((s) => (
            <div key={s.id} style={submissionCard}>
              <p style={{ marginBottom: "8px" }}>
                <strong>Student:</strong> {s.student_name}
              </p>

              <p style={{ marginBottom: "8px" }}>
                <strong>Status:</strong> {s.status}
              </p>

              {s.file_url ? (
                <a
                  href={`http://127.0.0.1:8000${s.file_url}`}
                  target="_blank"
                  rel="noreferrer"
                  style={linkBtn}
                >
                  View Submission
                </a>
              ) : (
                <p style={{ color: "#999", margin: 0 }}>No file uploaded</p>
              )}
            </div>
          ))
        )}
      </div>
    </div>
  );
}

const panel = {
  background: "#fff",
  borderRadius: "16px",
  padding: "20px",
  boxShadow: "0 6px 18px rgba(0,0,0,0.08)"
};

const heading = {
  color: "#6a1b9a",
  marginBottom: "18px"
};

const formStyle = {
  display: "flex",
  flexDirection: "column",
  gap: "12px"
};

const inputStyle = {
  width: "100%",
  padding: "12px",
  borderRadius: "10px",
  border: "1px solid #ccc",
  outline: "none"
};

const primaryBtn = {
  background: "#7b1fa2",
  color: "#fff",
  border: "none",
  padding: "12px",
  borderRadius: "10px",
  cursor: "pointer",
  fontWeight: "bold"
};

const card = {
  border: "1px solid #eee",
  borderRadius: "12px",
  padding: "14px",
  background: "#fafafa",
  marginTop: "12px"
};

const submissionCard = {
  border: "1px solid #eee",
  borderRadius: "12px",
  padding: "14px",
  background: "#fafafa",
  marginBottom: "12px"
};

const linkBtn = {
  display: "inline-block",
  background: "#1565c0",
  color: "#fff",
  textDecoration: "none",
  padding: "8px 14px",
  borderRadius: "8px"
};

export default AssignmentsTeacher;
